(function(a){"use strict";const i={modelCache:null,apiUrl:null,init:function(n){this.apiUrl=n},loadAllModels:async function(){if(this.modelCache)return this.modelCache;const o=await new ElanRegistryAPI().post(this.apiUrl,{action:"getAllYearModels"});if(!o.success||!o.yearModels)throw new Error("Failed to load models: "+(o.message||"no model data"));return this.modelCache=o.yearModels,this.modelCache},populateModelDropdown:async function(n,o){if(!n||!o||o.length===0)return;const s=await this.loadAllModels();o.find("option:not(:first)").remove();const e=s[n]||[];e.forEach(function(t){o.append(new Option(t.text,t.value))}),o.prop("disabled",e.length===0),o.trigger("change")}};a.ModelLoader=i})(window);
